typedef float rational_t;

extern "C" float sqrtf(float);
#define __fsqrt sqrtf

class vector3d
{
public:
  rational_t x, y, z;

  inline rational_t length() const
  {
    return (rational_t)__fsqrt(x*x + y*y + z*z);
  }
};

class vector4d
{
public:
  rational_t x, y, z, w;
};

class matrix4x4
{
public:
  vector4d x __attribute__((aligned(16)));
  vector4d y;
  vector4d z;
  vector4d w;
};

class quaternion
{
public:
  quaternion(const matrix4x4 &M);

  rational_t a;
  rational_t b;
  rational_t c;
  rational_t d;
};

class po
{
private:
  matrix4x4 m;

public:
  const matrix4x4& get_matrix() const
  {
    return m;
  }

  inline rational_t get_scale() const
  {
    return ((const vector3d&)m).length();
  }

  quaternion get_quaternion() const;
};

quaternion po::get_quaternion() const
{
  matrix4x4 orient_m = get_matrix();
  rational_t s = 1.0f / get_scale();

  orient_m.x.x *= s;  orient_m.x.y *= s;  orient_m.x.z *= s;
  orient_m.y.x *= s;  orient_m.y.y *= s;  orient_m.y.z *= s;
  orient_m.z.x *= s;  orient_m.z.y *= s;  orient_m.z.z *= s;

  return quaternion(orient_m);
}
